/* PdaCargoReceiveMapper.insertMasterDest : Master Dest insert */
	INSERT INTO TB_BMS_MASTER_DEST (
		MBL_NO
		, PIECES
		, AR_DATE
		, AR_TIME
		, DEST_DATE
		, DEST_TIME
		, REGISTER_USER_ID
		, REGISTER_DATE_TIME
		, UPDATE_USER_ID
		, UPDATE_DATE_TIME
	)VALUES(
		#{mblNo}
		, #{pieces}
		, #{arDate}
		, #{arTime}




			, CONVERT(CHAR(10), #{editDestDate}, 23)


			, CONVERT(CHAR(10), GETDATE(), 23)




			, SUBSTRING(#{editDestDate}, 12, 5)


			, FORMAT(GETDATE(), 'HH:mm')


		, #{updateUserId}
		, GETDATE()
		, #{updateUserId}
		, GETDATE()
	);

mapper.update:
/* PdaCargoReceiveMapper.updateMasterDest : Master Dest update */
UPDATE 
	TB_BMS_MASTER_DEST
SET
	PIECES = #{pieces}

	, AR_DATE = #{arDate}


	, AR_TIME = #{arTime}

	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = GETDATE()

		, DEST_DATE = CONVERT(CHAR(10), #{editDestDate}, 23)
		, DEST_TIME = SUBSTRING(#{editDestDate}, 12, 5)

WHERE 
	SEQ = #{seq}
